public sealed class SourcingSupplySqlTests(MarketFixture fixture):IClassFixture<MarketFixture>
{
    private static string Id()=>Guid.NewGuid().ToString("N");
    private sealed class FixedClock(DateTimeOffset instant):TimeProvider{public override DateTimeOffset GetUtcNow()=>instant;}
    private static string Text(JsonNode node,string name)=>node[name]!.GetValue<string>();
    private sealed record Scenario(HttpClient Customer,string Owner,string Request,string Listing,string Model,string Variant,string Offer,string OfferLine,string Task,SourcingSupplyStartInput Start);
    private static string OfferRoute(Scenario s,bool admin=true)=>$"/api/{(admin?"admin/":"")}sourcing/requests/{s.Request}/offers/{s.Offer}";
    private static string SupplyRoute(Scenario s,bool admin=true)=>$"/api/{(admin?"admin/":"")}sourcing/requests/{s.Request}/supply/{s.Task}";
    private static string ReceiveRoute(Scenario s,string receipt)=>$"/api/admin/inventory/sourcing-requests/{s.Request}/tasks/{s.Task}/receipts/{receipt}";
    private static string InventoryRoute(Scenario s)=>"/api/admin/inventory/sourcing-tasks/"+s.Task;
    private static async Task<JsonNode> Body(HttpResponseMessage response,HttpStatusCode expected=HttpStatusCode.OK,string? capture=null)
    {
        using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.StatusCode==expected,$"HTTP {(int)response.StatusCode}, expected {(int)expected}: {raw}");Assert.Contains("no-store",response.Headers.CacheControl!.ToString());if(capture is not null&&Environment.GetEnvironmentVariable("SHOP_SUPPLY_WIRE_DIR") is {Length:>0} directory){Directory.CreateDirectory(directory);await File.WriteAllTextAsync(Path.Combine(directory,capture+".json"),raw);}return raw.Length==0?new JsonObject():JsonNode.Parse(raw)!;}
    }
    private async Task<T> Scope<T>(Func<IServiceProvider,Task<T>> action){await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();return await action(scope.ServiceProvider);}
    private static HttpClient CopyClient(SqlFactory factory,HttpClient original)
    {
        var copy=factory.CreateClient(new(){HandleCookies=false});foreach(var header in original.DefaultRequestHeaders)copy.DefaultRequestHeaders.TryAddWithoutValidation(header.Key,header.Value);return copy;
    }
    private async Task GrowCatalogRepresentation(Scenario s)
    {
        await Scope(async sp=>{var db=sp.GetRequiredService<CatalogDbContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);var product=await db.Products.Include(p=>p.Attributes).SingleAsync(p=>p.Id==s.Model);for(var i=0;i<65;i++){var id=Id();db.AttributeDefinitions.Add(new(){Id=id,Key="supply-capacity-"+id,DataType=AttributeDataType.Text,Translations=[new(){Locale="fa",Name="ویژگی مصنوعی"},new(){Locale="en",Name="Synthetic attribute"}]});db.CategoryAttributes.Add(new(){CategoryId=product.CategoryId,AttributeId=id,ShowInSpecs=true,IsComparable=true});product.Attributes.Add(new(){AttributeId=id,ValueTextFa="مقدار نمونه",ValueTextEn="Synthetic value"});}await db.SaveChangesAsync();return true;});
    }
    private async Task<(HttpClient Client,string Owner)> Customer()
    {
        return await Scope(async sp=>{var users=sp.GetRequiredService<UserManager<ShopUser>>();var username="supply"+Id();var user=new ShopUser{UserName=username,Email=username+"@example.test",EmailConfirmed=true,DisplayName="Synthetic supply SQL customer"};Assert.True((await users.CreateAsync(user,fixture.Sql.Password)).Succeeded);var session=await sp.GetRequiredService<AuthService>().PasswordAsync(new(username,fixture.Sql.Password),true,true,false,default);var client=fixture.Sql.Factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");client.DefaultRequestHeaders.Authorization=new("Bearer",session.AccessToken);return(client,user.Id);});
    }
    private async Task<HttpClient> IndependentInventoryActor()
    {
        // Policy/receipt isolation needs a second real actor, not another HTTP
        // rate-limit test after the five fixture roles consumed 15 auth POSTs.
        return await Scope(async sp=>{var users=sp.GetRequiredService<UserManager<ShopUser>>();var name="supplyinventory"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,RequireMfa=true};Assert.True((await users.CreateAsync(user,fixture.Sql.Password)).Succeeded);Assert.True((await users.AddToRoleAsync(user,"InventoryManager")).Succeeded);var auth=sp.GetRequiredService<AuthService>();var pending=await auth.PasswordAsync(new(name,fixture.Sql.Password),true,true,true,default);Assert.True(pending.RequiresMfa);var setup=JsonSerializer.SerializeToNode(await auth.SetupMfaAsync(user.Id,(await users.GetSecurityStampAsync(user))!,false,null,default),new JsonSerializerOptions(JsonSerializerDefaults.Web))!;var current=(await users.FindByIdAsync(user.Id))!;var verified=await auth.VerifyMfaAsync(user.Id,(await users.GetSecurityStampAsync(current))!,false,Totp.Code(Text(setup,"secret"),DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30),"supply-sql-"+Id(),default);var client=fixture.Sql.Factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");client.DefaultRequestHeaders.Add("X-Sayman-Client","admin");client.DefaultRequestHeaders.Add("X-Sayman-Admin","1");client.DefaultRequestHeaders.Authorization=new("Bearer",verified.AccessToken);return client;});
    }
    private async Task<Scenario> Create(bool start=true)
    {
        var key=Id();var model=new CatalogModelInput("phones","samsung","supply-"+key,[new("fa","گوشی تأمین مصنوعی "+key,"صرفاً آزمون SQL"),new("en","Synthetic supply phone "+key,"Synthetic SQL data only")],[new("battery",TextFa:"باتری نمونه",TextEn:"Synthetic battery")],["/products/phone-green.svg"],null);
        var created=await Body(await fixture.Writer.PostAsJsonAsync("/api/admin/market/models",new CreateMarketModelInput(model,new("Published","qa-supply",key,"منبع نمونه","Synthetic source",null,"unknown",null,null,null,true))));var listing=Text(created,"id");var person=await Customer();var cart=await Body(await person.Client.GetAsync("/api/cart/en/sourcing"));cart=await Body(await person.Client.PutAsJsonAsync("/api/cart/en/sourcing",new CartSourcingInput([new(listing,2)],cart["version"]?.GetValue<string>())));var candidate=cart["lines"]![0]!["candidate"]!;var modelId=Text(candidate["model"]!,"id");var submitted=await Body(await person.Client.PostAsJsonAsync("/api/cart/en/sourcing/submit",new SourcingSubmitInput(Id(),Text(cart,"version"),[new(listing,Text(candidate,"fingerprint"))])),HttpStatusCode.Created);var request=Text(submitted,"id");var variant=Id();
        await Scope(async sp=>{var db=sp.GetRequiredService<CatalogDbContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);var product=await db.Products.Include(p=>p.PurchaseMethods).SingleAsync(p=>p.Id==modelId);product.Status="Published";product.PurchaseMethods.Add(new(){ProductId=modelId,MethodId="online"});db.Variants.Add(new(){Id=variant,ProductId=modelId,Sku="QA-SUPPLY-"+key,PriceRial=123,IsActive=true,LabelFa="نسخهٔ واقعی نمونه",LabelEn="Actual synthetic SKU",WarrantyFa="گارانتی مصنوعی آزمون",WarrantyEn="Synthetic QA warranty"});await db.SaveChangesAsync();return true;});
        using var finance=await fixture.ReuseStaff("FinanceManager");var parent=await Body(await finance.GetAsync($"/api/admin/sourcing/requests/{request}"));var sku=await Body(await finance.GetAsync($"/api/admin/sourcing/requests/{request}/offer-skus/{variant}?listingId={listing}"));var offer=Id();var line=Id();var now=DateTimeOffset.UtcNow;var save=new SourcingOfferSaveInput(Id(),Text(parent["summary"]!,"version"),null,[new(line,listing,variant,2,"9007199254740993",Text(sku,"materialFingerprint"),Text(sku,"currentFingerprint"))],"شرایط مصنوعی؛ صرفاً رضایت پیگیری تأمین، بدون پرداخت.","Synthetic consent to supply follow-up only, no payment.",now.AddMinutes(20),now.AddHours(2));
        var route=$"/api/admin/sourcing/requests/{request}/offers/{offer}";await Body(await finance.PutAsJsonAsync(route,save));var draft=await Body(await finance.GetAsync(route));await Body(await finance.PostAsJsonAsync(route+"/publish",new SourcingOfferPublishInput(Id(),Text(draft,"requestVersion"),Text(draft["offer"]!["summary"]!,"version"),Text(draft["offer"]!["summary"]!,"termsHash"))));var customerRoute=$"/api/sourcing/requests/{request}/offers/{offer}";var published=await Body(await person.Client.GetAsync(customerRoute));await Body(await person.Client.PostAsJsonAsync(customerRoute+"/accept",new SourcingOfferActionInput(Id(),Text(published,"requestVersion"),Text(published["offer"]!["summary"]!,"version"),Text(published["offer"]!["summary"]!,"termsHash"))));var accepted=await Body(await person.Client.GetAsync(customerRoute));var startInput=new SourcingSupplyStartInput(Id(),Text(accepted,"requestVersion"),Text(accepted["offer"]!["summary"]!,"version"),Text(accepted["offer"]!["summary"]!,"termsHash"));var scenario=new Scenario(person.Client,person.Owner,request,listing,modelId,variant,offer,line,Id(),startInput);
        if(start){using var sales=await fixture.ReuseStaff("SalesManager");await Body(await sales.PutAsJsonAsync(OfferRoute(scenario)+"/supply/"+scenario.Task,startInput));}return scenario;
    }
    private static SourcingSupplySourceInput Source(JsonNode detail,string? reference=null)=>new(Id(),Text(detail,"requestVersion"),Text(detail["task"]!,"version"),"manual","PRIVATE-SOURCE-0001","منبع خصوصی نمونه","Private synthetic supplier",reference,DateTimeOffset.UtcNow.AddMinutes(-1),"پیگیری عمومی نمونه","Synthetic public follow-up",null,"PRIVATE-SUPPLY-NOTE: synthetic supplier details.");
    private static SourcingSupplyCloseInput Close(JsonNode detail)=>new(Id(),Text(detail,"requestVersion"),Text(detail["task"]!,"version"),"supplier_unavailable","پیگیری تأمین پایان یافت؛ دریافت واقعی محفوظ است.","Supply follow-up ended; actual receipts remain.","PRIVATE-SUPPLY-CLOSE-NOTE");
    private async Task<ReceivingUnitMappingData> Mapping(Scenario s,HttpClient inventory,string? capture=null)
    {
        var id=Id();var input=new ReceivingUnitMappingInput(Id(),"Holoo-"+Id(),"001","Main","each",s.Variant,1,1,"عدد نمونه","Synthetic each",true,null);await Body(await inventory.PutAsJsonAsync("/api/admin/inventory/receiving-unit-mappings/"+id,input),capture:capture);return JsonSerializer.Deserialize<ReceivingUnitMappingData>((await Body(await inventory.GetAsync("/api/admin/inventory/receiving-unit-mappings/"+id))).ToJsonString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))!;
    }
    private static SourcingReceiptInput Receiving(JsonNode view,ReceivingUnitMappingData mapping,string quantity="1",bool historical=false,string? document=null)
    {
        var task=view["task"]!;return new(Id(),Text(task,"requestVersion"),Text(task["task"]!,"version"),"manual",mapping.OriginSystem,mapping.CompanyKey,mapping.WarehouseKey,document??"RECEIPT-"+Id(),DateTimeOffset.UtcNow.AddMinutes(-1),"ثبت دریافت واقعی مصنوعی SQL",historical,[new(Text(task["lines"]![0]!,"offerLineId"),"001",mapping.Id,mapping.Version,quantity,Text(view["stock"]![0]!,"trackingMode"),view["stock"]![0]!["version"]?.GetValue<string>(),[])]);
    }
    private async Task<(int OnHand,int Reserved,int Movements,int InventoryReceipts,int Applications,int Received,int Orders,int Reservations)> Counters(Scenario s)=>await Scope(async sp=>{var db=sp.GetRequiredService<InventoryDbContext>();var market=sp.GetRequiredService<MarketDbContext>();var stock=await db.Stock.AsNoTracking().SingleOrDefaultAsync(x=>x.VariantId==s.Variant);return(stock?.OnHand??0,stock?.Reserved??0,await db.Movements.CountAsync(m=>m.VariantId==s.Variant),await db.SourcingReceipts.CountAsync(r=>r.TaskId==s.Task),await market.SourcingSupplyReceiptApplications.CountAsync(r=>r.TaskId==s.Task),await market.Set<SourcingSupplyTaskLine>().Where(l=>l.TaskId==s.Task).SumAsync(l=>l.ReceivedQuantity),await sp.GetRequiredService<SalesDbContext>().Orders.CountAsync(),await db.Reservations.CountAsync());});
    private static void NoPrivateFields(JsonNode node)
    {
        var json=node.ToJsonString();foreach(var name in new[]{"ownerId","actorId","sourceKind","sourceKey","sourceNameFa","sourceNameEn","reference","internalNote","protectedNote","totalRial","unitPriceRial","costRial","serial","imei1","imei2"})Assert.DoesNotContain("\""+name+"\":",json,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("PRIVATE-SUPPLY",json);Assert.DoesNotContain("PRIVATE-SOURCE",json);
    }

