    {
        var s=await Create();using var customer=s.Customer;using var sales=await fixture.ReuseStaff("SalesManager");using var inventory=await fixture.ReuseStaff("InventoryManager");var initial=await Counters(s);Assert.Equal(0,initial.OnHand);var detail=await Body(await sales.GetAsync(SupplyRoute(s)));await Body(await sales.PostAsJsonAsync(SupplyRoute(s)+"/requested",Source(detail)));detail=await Body(await sales.GetAsync(SupplyRoute(s)));await Body(await sales.PostAsJsonAsync(SupplyRoute(s)+"/ordered",Source(detail,"ORDER-00042")));detail=await Body(await sales.GetAsync(SupplyRoute(s)));await Body(await sales.PostAsJsonAsync(SupplyRoute(s)+"/progress",new SourcingSupplyProgressInput(Id(),Text(detail,"requestVersion"),Text(detail["task"]!,"version"),DateTimeOffset.UtcNow.AddMinutes(-1),"منتظر دریافت واقعی","Awaiting actual receipt",null,"PRIVATE-SUPPLY-NOTE: progress.")),capture:"supply-mutation");
        var mapping=await Mapping(s,inventory,"mapping-mutation");await Body(await inventory.GetAsync("/api/admin/inventory/receiving-unit-mappings/"+mapping.Id),capture:"mapping");await Body(await inventory.GetAsync("/api/admin/inventory/receiving-unit-mappings?originSystem="+mapping.OriginSystem+"&companyKey=001&warehouseKey=Main&variantId="+s.Variant),capture:"mapping-page");
        var view=await Body(await inventory.GetAsync(InventoryRoute(s)));var input=Receiving(view,mapping);var receipt=Id();var first=await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,receipt),input),capture:"receive");var replay=await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,receipt),input),capture:"receive-replay");Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(first["lines"]!.ToJsonString(),replay["lines"]!.ToJsonString());await Body(await inventory.GetAsync("/api/admin/inventory/sourcing-receipts/"+receipt),capture:"receipt");
        var partial=await Body(await customer.GetAsync(SupplyRoute(s,false)));Assert.Equal("Partial",Text(partial["task"]!,"receiptProgress"));Assert.False(partial["reservedForRequest"]!.GetValue<bool>());view=await Body(await inventory.GetAsync(InventoryRoute(s)));await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,Id()),Receiving(view,mapping)));
        var admin=await Body(await sales.GetAsync(SupplyRoute(s)),capture:"admin-detail");Assert.Equal("Complete",Text(admin["task"]!,"receiptProgress"));Assert.Equal("Received",Text(admin["task"]!,"effectiveState"));Assert.True(admin["task"]!["isOpen"]!.GetValue<bool>());Assert.Contains("PRIVATE-SUPPLY",Text(admin,"internalNote"));await Body(await sales.GetAsync($"/api/admin/sourcing/requests/{s.Request}/supply"),capture:"admin-page");await Body(await sales.GetAsync(SupplyRoute(s)+"/events"),capture:"admin-events");
        await Body(await inventory.GetAsync("/api/admin/inventory/sourcing-tasks?query="+s.Task),capture:"inventory-page");var inventoryDetail=await Body(await inventory.GetAsync(InventoryRoute(s)),capture:"inventory-detail");NoPrivateFields(inventoryDetail["task"]!);var owner=await Body(await customer.GetAsync(SupplyRoute(s,false)),capture:"customer-detail");NoPrivateFields(owner);Assert.False(owner["canPay"]!.GetValue<bool>());Assert.False(owner["canCheckout"]!.GetValue<bool>());await Body(await customer.GetAsync($"/api/sourcing/requests/{s.Request}/supply"),capture:"customer-page");NoPrivateFields(await Body(await customer.GetAsync(SupplyRoute(s,false)+"/events"),capture:"customer-events"));
        await Body(await customer.GetAsync($"/api/sourcing/requests/{s.Request}/events"),capture:"parent-events");await Body(await customer.GetAsync(OfferRoute(s,false)),capture:"accepted-offer");var final=await Counters(s);Assert.Equal(2,final.OnHand);Assert.Equal(0,final.Reserved);Assert.Equal(2,final.Movements);Assert.Equal(2,final.InventoryReceipts);Assert.Equal(2,final.Applications);Assert.Equal(2,final.Received);Assert.Equal(initial.Orders,final.Orders);Assert.Equal(initial.Reservations,final.Reservations);
    }

