    [Fact] public async Task StartAndReceiptReplayBindActorTargetAndPayloadBeforeCurrentVersions()
    {
        var s=await Create();using var customer=s.Customer;using var sales=await fixture.ReuseStaff("SalesManager");using var inventory=await fixture.ReuseStaff("InventoryManager");var start=await Body(await sales.PutAsJsonAsync(OfferRoute(s)+"/supply/"+s.Task,s.Start));Assert.True(start["replayed"]!.GetValue<bool>());await Body(await sales.PutAsJsonAsync(OfferRoute(s)+"/supply/"+Id(),s.Start),HttpStatusCode.Conflict);using var otherInventory=await IndependentInventoryActor();var mapping=await Mapping(s,inventory);var input=Receiving(await Body(await inventory.GetAsync(InventoryRoute(s))),mapping);var receipt=Id();await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,receipt),input));
        await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,receipt),input with{Reason="Different physical reason"}),HttpStatusCode.Conflict);await Body(await inventory.GetAsync("/api/admin/inventory/sourcing-receipts/"+receipt+"/commands/"+input.RequestId));await Body(await otherInventory.GetAsync("/api/admin/inventory/sourcing-receipts/"+receipt+"/commands/"+input.RequestId),HttpStatusCode.NotFound);var fresh=Receiving(await Body(await inventory.GetAsync(InventoryRoute(s))),mapping) with{SourceReceiptKey=input.SourceReceiptKey,Channel="csv"};var duplicate=await Body(await otherInventory.PostAsJsonAsync(ReceiveRoute(s,Id()),fresh),HttpStatusCode.Conflict);Assert.Equal("receiving_external_identity_conflict",Text(duplicate,"title"));Assert.Equal(1,(await Counters(s)).OnHand);
