    [Fact] public async Task CancelledSupplyAndClosedParentAcceptOnlyExplicitHistoricalPhysicalReceipt()
    {
        var s=await Create();using var customer=s.Customer;using var sales=await fixture.ReuseStaff("SalesManager");using var inventory=await fixture.ReuseStaff("InventoryManager");var detail=await Body(await sales.GetAsync(SupplyRoute(s)));await Body(await sales.PostAsJsonAsync(SupplyRoute(s)+"/cancel",Close(detail)));var parent=await Body(await customer.GetAsync($"/api/sourcing/requests/{s.Request}"));await Body(await customer.PostAsJsonAsync($"/api/sourcing/requests/{s.Request}/cancel",new SourcingActionInput(Id(),Text(parent["summary"]!,"version"))));var mapping=await Mapping(s,inventory);var view=await Body(await inventory.GetAsync(InventoryRoute(s)));Assert.True(view["task"]!["requiresHistoricalAcknowledgement"]!.GetValue<bool>());var input=Receiving(view,mapping);var missing=await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,Id()),input),HttpStatusCode.Conflict);Assert.Equal("sourcing_supply_historical_ack_conflict",Text(missing,"title"));await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,Id()),input with{RequestId=Id(),AcknowledgeHistorical=true}));
        var historical=await Body(await customer.GetAsync(SupplyRoute(s,false)));Assert.Equal("Cancelled",Text(historical["task"]!,"state"));Assert.True(historical["task"]!["requiresNewOffer"]!.GetValue<bool>());Assert.False(historical["canPay"]!.GetValue<bool>());await Scope(async sp=>{var market=sp.GetRequiredService<MarketDbContext>();Assert.Equal("Cancelled",(await market.SourcingRequests.SingleAsync(r=>r.Id==s.Request)).State);var offer=await market.SourcingOffers.SingleAsync(o=>o.Id==s.Offer);Assert.Equal("Accepted",offer.State);Assert.False(offer.IsActive);return true;});
    }

    [Theory][InlineData("application")][InlineData("audit")]
    public async Task MarketApplicationOrAuditFailureRollsBackInventoryAndProgressTogether(string failure)
    {
        if(failure is not ("application" or "audit"))throw new ArgumentException("Use only a fixed QA failure-injection target.",nameof(failure));
        var s=await Create();using var customer=s.Customer;using var inventory=await fixture.ReuseStaff("InventoryManager");var mapping=await Mapping(s,inventory);var input=Receiving(await Body(await inventory.GetAsync(InventoryRoute(s))),mapping);var receipt=Id();var route=ReceiveRoute(s,receipt);var before=await Counters(s);
        var addConstraint=failure=="application"?"ALTER TABLE [market].[SourcingSupplyReceiptApplications] WITH NOCHECK ADD CONSTRAINT [CK_SupplyAtomicFailure] CHECK (1=0)":"ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT [CK_SupplyAtomicFailure] CHECK ([Resource]<>N'"+route+"')";
        var dropConstraint=failure=="application"?"ALTER TABLE [market].[SourcingSupplyReceiptApplications] DROP CONSTRAINT [CK_SupplyAtomicFailure]":"ALTER TABLE [identity].[Audit] DROP CONSTRAINT [CK_SupplyAtomicFailure]";
        await Scope(async sp=>{var db=sp.GetRequiredService<MarketDbContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync(addConstraint);return true;});
        try{await Body(await inventory.PostAsJsonAsync(route,input),HttpStatusCode.Conflict);}finally{await Scope(async sp=>{await sp.GetRequiredService<MarketDbContext>().Database.ExecuteSqlRawAsync(dropConstraint);return true;});}
        Assert.Equal(before,await Counters(s));await Scope(async sp=>{Assert.False(await sp.GetRequiredService<InventoryDbContext>().ReceivingCommands.AnyAsync(c=>c.CommandId==input.RequestId));Assert.False(await sp.GetRequiredService<IdentityDbContext>().Audit.AnyAsync(a=>a.Resource==route));return true;});await Body(await inventory.PostAsJsonAsync(route,input));Assert.Equal(1,(await Counters(s)).OnHand);Assert.Equal(1,(await Counters(s)).Received);
    }

    [Fact] public async Task ReceiveAndExplicitCloseRaceSerializeOnSameParentVersionWithoutLosingPhysicalFacts()
    {
        var s=await Create();using var customer=s.Customer;using var sales=await fixture.ReuseStaff("SalesManager");using var inventory=await fixture.ReuseStaff("InventoryManager");var mapping=await Mapping(s,inventory);var detail=await Body(await sales.GetAsync(SupplyRoute(s)));var input=Receiving(await Body(await inventory.GetAsync(InventoryRoute(s))),mapping);var close=Close(detail);var responses=await Task.WhenAll(inventory.PostAsJsonAsync(ReceiveRoute(s,Id()),input),sales.PostAsJsonAsync(SupplyRoute(s)+"/cancel",close));try{Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Conflict);}finally{foreach(var response in responses)response.Dispose();}var after=await Counters(s);var task=await Body(await sales.GetAsync(SupplyRoute(s)));if(Text(task["task"]!,"state")=="Cancelled"){Assert.Equal(0,after.OnHand);Assert.Equal(0,after.Received);}else{Assert.Equal(1,after.OnHand);Assert.Equal(1,after.Received);}Assert.Equal(after.OnHand,after.InventoryReceipts);Assert.Equal(after.InventoryReceipts,after.Applications);Assert.Equal(0,after.Reserved);
    }

    [Fact] public async Task CatalogRepresentationGrowthRequiresNewConsentButNeverBlocksAcknowledgedPhysicalFact()
    {
        var s=await Create();using var customer=s.Customer;using var inventory=await fixture.ReuseStaff("InventoryManager");var mapping=await Mapping(s,inventory);
        await GrowCatalogRepresentation(s);
        var view=await Body(await inventory.GetAsync(InventoryRoute(s)));Assert.True(view["task"]!["requiresHistoricalAcknowledgement"]!.GetValue<bool>());var input=Receiving(view,mapping);await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,Id()),input),HttpStatusCode.Conflict);var received=await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,Id()),input with{RequestId=Id(),AcknowledgeHistorical=true}));Assert.True(received["requiresNewOffer"]!.GetValue<bool>());Assert.Equal(1,(await Counters(s)).OnHand);
    }

    [Fact] public async Task AcceptedConsentWithUnrepresentableCurrentCatalogHasReadablePageButCannotStartSupply()
    {
        var s=await Create(start:false);using var customer=s.Customer;using var sales=await fixture.ReuseStaff("SalesManager");await GrowCatalogRepresentation(s);var page=await Body(await sales.GetAsync($"/api/admin/sourcing/requests/{s.Request}/supply"));Assert.Empty(page["items"]!.AsArray());Assert.True(page.AsObject().ContainsKey("startCandidate"));Assert.Null(page["startCandidate"]);var rejected=await Body(await sales.PutAsJsonAsync(OfferRoute(s)+"/supply/"+s.Task,s.Start with{RequestId=Id()}),HttpStatusCode.Conflict);Assert.Equal("sourcing_supply_reoffer_conflict",Text(rejected,"title"));
        await Scope(async sp=>{var market=sp.GetRequiredService<MarketDbContext>();Assert.False(await market.SourcingSupplyTasks.AnyAsync(t=>t.RequestId==s.Request));Assert.False(await market.SourcingSupplyCommandReceipts.AnyAsync(r=>r.RequestId==s.Request));var stock=sp.GetRequiredService<InventoryDbContext>();Assert.False(await stock.Stock.AnyAsync(row=>row.VariantId==s.Variant));Assert.False(await stock.SourcingReceipts.AnyAsync(r=>r.RequestId==s.Request));return true;});
    }

    [Fact] public async Task ExactPurchaseDeadlineKeepsHistoricalReplayButRequiresAcknowledgedReceiptAfterParentClose()
    {
        var s=await Create();using var customer=s.Customer;using var inventory=await fixture.ReuseStaff("InventoryManager");using var sales=await fixture.ReuseStaff("SalesManager");var initial=await Counters(s);var mapping=await Mapping(s,inventory);var firstInput=Receiving(await Body(await inventory.GetAsync(InventoryRoute(s))),mapping);var firstReceipt=Id();var first=await Body(await inventory.PostAsJsonAsync(ReceiveRoute(s,firstReceipt),firstInput));Assert.Equal(1,(await Counters(s)).OnHand);var accepted=await Body(await customer.GetAsync(OfferRoute(s,false)));var deadline=DateTimeOffset.Parse(Text(accepted["offer"]!["summary"]!,"purchaseUntil"),System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None);
        var keyDirectory=await Scope(sp=>{var repository=Assert.IsType<FileSystemXmlRepository>(sp.GetRequiredService<IOptions<KeyManagementOptions>>().Value.XmlRepository);return Task.FromResult(repository.Directory.FullName);});
        // This second server shares only this fixture's freshly generated DB
        // and key ring. It owns no cleanup and never reads the owner's secrets.
        await using var shiftedFactory=new SqlFactory(fixture.Sql.Connection,fixture.Sql.Password,keyDirectory,new FixedClock(deadline));using var lateCustomer=CopyClient(shiftedFactory,customer);using var lateInventory=CopyClient(shiftedFactory,inventory);using var lateSales=CopyClient(shiftedFactory,sales);
        Assert.Equal(deadline,shiftedFactory.Services.GetRequiredService<TimeProvider>().GetUtcNow());var replay=await Body(await lateInventory.PostAsJsonAsync(ReceiveRoute(s,firstReceipt),firstInput));Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(Text(first,"receiptId"),Text(replay,"receiptId"));Assert.Equal(first["lines"]!.ToJsonString(),replay["lines"]!.ToJsonString());Assert.Equal(1,(await Counters(s)).OnHand);
        var task=await Body(await lateSales.GetAsync(SupplyRoute(s)));Assert.True(task["task"]!["requiresNewOffer"]!.GetValue<bool>());var source=await Body(await lateSales.PostAsJsonAsync(SupplyRoute(s)+"/ordered",Source(task,"ORDER-AFTER-DEADLINE")),HttpStatusCode.Conflict);Assert.Equal("sourcing_supply_reoffer_conflict",Text(source,"title"));var parent=await Body(await lateCustomer.GetAsync($"/api/sourcing/requests/{s.Request}"));await Body(await lateCustomer.PostAsJsonAsync($"/api/sourcing/requests/{s.Request}/cancel",new SourcingActionInput(Id(),Text(parent["summary"]!,"version"))));
        var view=await Body(await lateInventory.GetAsync(InventoryRoute(s)));Assert.Equal("Cancelled",Text(view["task"]!["task"]!,"state"));Assert.True(view["task"]!["requiresHistoricalAcknowledgement"]!.GetValue<bool>());var lateInput=Receiving(view,mapping) with{ReceivedAt=deadline};var secondReceipt=Id();var unacknowledged=await Body(await lateInventory.PostAsJsonAsync(ReceiveRoute(s,secondReceipt),lateInput),HttpStatusCode.Conflict);Assert.Equal("sourcing_supply_historical_ack_conflict",Text(unacknowledged,"title"));Assert.Equal(1,(await Counters(s)).OnHand);var received=await Body(await lateInventory.PostAsJsonAsync(ReceiveRoute(s,secondReceipt),lateInput with{RequestId=Id(),AcknowledgeHistorical=true}));Assert.True(received["requiresNewOffer"]!.GetValue<bool>());
        var historical=await Body(await lateCustomer.GetAsync(SupplyRoute(s,false)));Assert.Equal("Cancelled",Text(historical["task"]!,"state"));Assert.Equal("Complete",Text(historical["task"]!,"receiptProgress"));Assert.False(historical["task"]!["isOpen"]!.GetValue<bool>());Assert.False(historical["canPay"]!.GetValue<bool>());Assert.False(historical["canCheckout"]!.GetValue<bool>());var final=await Counters(s);Assert.Equal(2,final.OnHand);Assert.Equal(2,final.Received);Assert.Equal(2,final.InventoryReceipts);Assert.Equal(2,final.Applications);Assert.Equal(0,final.Reserved);Assert.Equal(initial.Orders,final.Orders);Assert.Equal(initial.Reservations,final.Reservations);
        await Scope(async sp=>{var market=sp.GetRequiredService<MarketDbContext>();Assert.Equal("Cancelled",(await market.SourcingRequests.SingleAsync(r=>r.Id==s.Request)).State);var offer=await market.SourcingOffers.SingleAsync(o=>o.Id==s.Offer);Assert.Equal("Accepted",offer.State);Assert.False(offer.IsActive);Assert.Equal(deadline,offer.PurchaseUntil);Assert.Single(await market.SourcingOfferAcceptances.Where(a=>a.OfferId==s.Offer).ToArrayAsync());Assert.False(await market.SourcingSupplyCommandReceipts.AnyAsync(r=>r.TaskId==s.Task&&r.Operation=="ordered"));return true;});
    }

